ROOT = Path(__file__).resolve().parent
SRC = ROOT.parents[2] / 'src' / 'edp8'
def module(name):
    spec = importlib.util.spec_from_file_location(name, SRC / (name + '.py'))
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m
avatars, icons = module('avatars'), module('icons')
def avatar(size=36, who='owner'):
    return avatars.role_avatar_svg(who, size=size) if who in ('architect','engineer') else avatars.human_avatar_svg({'owner':'human-03','ravi':'human-03','x':'human-02'}[who], size)
def icon(name, size=18): return icons.icon(name, size)
def e(s): return escape(s)

