    nav=''.join(f'<div class="nav-item {"active" if page==p else ""}">{icon(i)}{label}</div>' for p,i,label in [('inbox','inbox','My inbox'),('epics','epic','Projects'),('tickets','ticket','Tickets'),('activity','thread','Activity')])
    convos=[('epic-733b165bd7','Q1 (design): Is the web','architect'),('epic-cf3d352b92','Owner decisions to follow','owner'),('s-fecce55fb8','P0 skeleton is built and the','engineer'),('s-13cd244cc9','Architect handoff for S10','architect'),('s-ac1c99a2cb','Architect handoff for the S2','architect')]
