def epics():
    rows=''.join(f'<article class="epic-row"><div><span class="epic-id">{tid}</span><span class="epic-title">{e(title)}</span></div><div class="epic-meta">{passed} / {total} passed<div class="progress"><span style="width:{100 if total and passed==total else 0}%"></span></div></div><div class="epic-meta">{date}</div><span class="badge {status.lower().replace(" ","-")}">{status}</span><span class="chevron">›</span></article>' for tid,title,passed,total,date,status in EPICS)
    return '<section class="epics-content"><h2 class="page-title">21 epics</h2><div class="filter"><select aria-label="Status"><option>any status</option></select><input aria-label="Search" placeholder="search words in epic titles"><button>Filter</button><a class="clear">clear</a></div><div class="epic-list">'+rows+'</div></section>'
def contrast(a,b):
    def lum(h):
        c=[int(h[i:i+2],16)/255 for i in (1,3,5)]
        c=[v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4 for v in c]
        return sum(v*w for v,w in zip(c,(.2126,.7152,.0722)))
    x,y=sorted([lum(a),lum(b)])
    return (y+.05)/(x+.05)
def tile(k):
    t=THEMES[k]
    sw=[('Canvas','#FFFFFF'),('Panel',t['panel']),('Raised',t['raised']),('Hairline',t['border']),('Primary text',t['text']),('Secondary',t['secondary']),('Muted text',t['muted']),('Input border',t['control']),('Orange',t['brand']),('Hover',t['brand_hover']),('Pressed',t['brand_active']),('Selected wash',t['tint'])]
    swatches=''.join(f'<div><div class="swatch-color" style="background:{v}"></div><div class="swatch-name">{n}</div><div class="swatch-hex">{v}</div></div>' for n,v in sw)
    statuses=''.join(f'<div class="status-sample"><span class="badge {cl}">{label}</span><span class="mono">{t[key]} text<br>{t[key+"_bg"]} fill</span></div>' for cl,label,key in [('done','Done','success'),('blocked','Blocked','danger'),('in-progress','In progress','progress'),('review','Review','review')])
    return f'''<div class="tile"><header class="tile-head"><div><div class="tile-eyebrow">edp8 board / visual direction {k}</div><h1>{t['name']}</h1><p>{t['tagline']}</p></div><div class="tile-number">{k}</div></header><div class="tile-grid"><div><h2>01 / Surface & accent palette</h2><div class="swatches">{swatches}</div><h2>02 / Semantic status pairs</h2><div class="status-samples">{statuses}</div><p class="tile-spec">Link {t['link']} · Focus {t['brand']} / 2 px, offset 2 px<br>Neutral hover {t['hover']} · Status always includes a written label.</p><h2>03 / Accent behavior</h2><div class="button-states"><button>Default</button><button style="background:{t['brand_hover']}">Hover</button><button style="background:{t['brand_active']}">Pressed</button></div><p class="tile-spec">Orange text / white: <b>{contrast(t['brand'],'#FFFFFF'):.2f}:1</b><br>White text / orange fill: <b>{contrast(t['brand'],'#FFFFFF'):.2f}:1</b><br>Small labels use this deep orange; no bright orange body copy.</p></div><div><h2>04 / Type & rhythm</h2><div class="type-row"><span class="type-label">{'30 / 34' if k=='B' else '24 / 32'} · page</span><span style="font:500 {'30' if k=='B' else '24'}px var(--heading)">21 epics</span></div><div class="type-row"><span class="type-label">{'21' if k=='B' else '18'} / 26 · channel</span><span style="font:650 {'21' if k=='B' else '18'}px var(--heading)">owner · My inbox</span></div><div class="type-row"><span class="type-label">{'16 / 26' if k=='B' else '14 / 24'} · report</span><span style="font-family:{'Georgia,serif' if k=='B' else 'var(--font)'};font-size:{'16' if k=='B' else '14'}px">The recenter hitch</span></div><div class="type-row"><span class="type-label">12 / 18 · meta</span><span style="font-size:12px">4 / 4 passed · 2026-08-23</span></div><div class="type-row"><span class="type-label">11 / 17 · ID</span><span class="mono" style="font-size:11px">epic-f1b4f138e9</span></div><p class="tile-spec">{'Georgia headings & report; Segoe UI controls.' if k=='B' else 'Segoe UI interface & report; Consolas identifiers.'}<br>Spacing: 4 / 8 / 12 / 16 / 24 / 32 px<br>Controls: 40 px · Cards: {t['radius']} radius<br>{'Square badges · flat rules · no shadow' if k=='B' else ('Pill badges · 14 px cards · 4 px / 16 px soft shadow' if k=='C' else 'Pill badges · 6 px controls · flat list rules')}</p><h2>05 / Component specimen</h2><div class="samples"><div class="sample-title">S2 engineer report</div><p>Endless-flight substrate · report v1</p><div class="sample-actions"><span class="badge review">Review</span><button>Send</button></div></div><p class="tile-spec">3 px epic stripe · 1 px surface borders<br>272 px sidebar / 280 px context / 76 px header<br>24 px content padding · white reading canvas</p></div></div><footer class="tile-footer"><div><strong>Orange earns its place.</strong><br>Brand, active navigation, primary action, focus and epic stripe.</div><div><strong>Reading stays neutral.</strong><br>No orange page wash, long paragraphs, or success indicators.</div></footer></div>'''

BASE += '\n.epic-row{padding-top:10px;padding-bottom:10px}.epic-id{margin-bottom:2px;line-height:16px}.epic-title{line-height:21px}.theme-A .epic-row,.theme-B .epic-row,.theme-C .epic-row{min-height:76px}.theme-C .epic-list{gap:6px}.theme-B .badge.done{background:var(--success-bg)}.theme-B .badge.blocked{background:var(--danger-bg)}.theme-B .badge.in-progress{background:var(--progress-bg)}.theme-B .badge.review{background:var(--review-bg)}.theme-B .samples{border-left:1px solid var(--border);border-top:3px solid var(--brand);background:#fff}\n'

for k,t in THEMES.items():
    (ROOT/f'concept-{k}.css').write_text(css(k),encoding='utf-8')
    for page in ('inbox','epics','tiles'):
        body=tile(k) if page=='tiles' else sidebar(page)+f'<main class="main"><header class="channel"><div><h1>{"owner · My inbox" if page=="inbox" else "Epics"}</h1><p>Project-persistent board workspace</p></div></header>'+ (inbox() if page=='inbox' else epics())+'</main>'
        (ROOT/f'concept-{k}-{page}.html').write_text(f'<!DOCTYPE html><html lang="en"><meta charset="UTF-8"><title>{t["name"]} — {page}</title><link rel="stylesheet" href="concept-{k}.css"><body class="theme-{k}">{body}</body></html>',encoding='utf-8')

(ROOT/'palette.json').write_text(json.dumps(THEMES,indent=2),encoding='utf-8')
print('Built 9 HTML mockups and 3 CSS sources.')
